import{_ as i,l as o,o as e,c as l,v as t,p as s,x as n,d,i as h,S as u}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"情绪指标：两融与换手","description":"","frontmatter":{"title":"情绪指标：两融与换手","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/cn-sentiment-indicators.md","filePath":"quant/cn-sentiment-indicators.md","lastUpdated":1789023840000}'),E={name:"quant/cn-sentiment-indicators.md"};function c(p,a,A,B,m,_){const r=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="情绪指标-两融与换手" tabindex="-1">情绪指标：两融与换手 <a class="header-anchor" href="#情绪指标-两融与换手" aria-label="Permalink to &quot;情绪指标：两融与换手&quot;">​</a></h1><div class="epigraph"><p>两融余额与换手是可公开观察的交易热度：前者混杂杠杆多头与稀薄空头，后者在 A 股更接近投机而不是流动性溢价。当指标当情绪，先拆科目、再扣制度。</p><footer>—— Baker and Wurgler, Investor Sentiment and the Cross-Section of Stock Returns, Journal of Finance, 2006；Liu, Stambaugh and Yuan, Size and Value in China, JFE, 2019；交易所两融与成交公开数据</footer></div><p><a href="/quant/cn-quant-regulation-history">上一课</a>说明监管窗口会改写交易行为。本课的缺口是<strong>把两融与换手当截面/时序情绪代理</strong>：Baker 与 Wurgler（2006）的情绪对美股截面；A 股最方便的公开热度是融资余额、融券余量与换手。<a href="/quant/cn-turnover-factor">换手因子</a> 已写高换手随后收益偏低；<a href="/quant/cn-margin-trading">两融保证金</a> 已写杠杆机制。本课不重做因子构造全文，而写如何把这些量当<strong>情绪状态</strong>进入择时或条件因子，并避免把融资当「聪明钱」。后课利率债换市场。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>融资余额上升可以是：杠杆乐观、新标的扩容、或股价上涨的机械市值效应。融券余量远小于融资，且受标的与转融通政策截断，不能当对称的悲观投票。把「两融余额」当单一情绪指数，符号与因果都混。问题是分列：融资余额/市值、融券余量/流通、融资买入额、以及换手。制度断点（保证金比例调整、暂停转融券）必须从情绪里剔出，否则 2024 年融券下降会被当成「情绪改善」。</p><p>换手：Liu–Stambaugh–Yuan 将其视为中国投机代理。高换手股票随后弱，与 Amihud 流动性溢价符号冲突。当情绪用：市场整体换手高可能对应散户热度与后续弱收益；个股换手是截面。两者不要加总成一个无名指数而不做标准化与制度过滤（涨跌停日换手不可比）。</p><h3 id="披露时钟" tabindex="-1">披露时钟 <a class="header-anchor" href="#披露时钟" aria-label="Permalink to &quot;披露时钟&quot;">​</a></h3><p>两融数据有交易所披露时点，终端有入库延迟。点-in-time 用披露后可知的最新值，不能用当日盘中尚未公布的余额去「预测」当日收益。这与分析师共识课同一纪律。北向持股披露是另一序列，见北向课，不要与两融混成「外资情绪」除非声明。</p><p><span class="marginnote">涨跌停锁定日成交量塌缩，换手变低，不是情绪突然冷静，是黑洞。情绪指标应标记锁定状态或剔除。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>构造：市场级融资余额相对自由流通市值、换手的截面中位数或市值加权。标准化用过去滚动而非全样本。条件因子：在高情绪期降低小盘/高换手暴露，或扩大价值——须预先登记，见研究日志，避免挖到 Baker–Wurgler 的 A 股再版。与监管日历正交化：在公告窗口用哑元或分开估计。</p><p>验证：情绪应与 IPO 热度、换手、封闭式基金溢价等其他代理同向，但 A 股封闭式基金样本有限，不要硬造 BW 六指标。能解释随后异常收益的增量，才留下；否则只当风险监控（杠杆热度）。</p><h3 id="融券余量不是空头情绪的充分统计量" tabindex="-1">融券余量不是空头情绪的充分统计量 <a class="header-anchor" href="#融券余量不是空头情绪的充分统计量" aria-label="Permalink to &quot;融券余量不是空头情绪的充分统计量&quot;">​</a></h3><p>余量受供给约束。供给收缩时余量下降，可能是政策而不是空头平仓。应用标的家数、费率（若可得）辅助。期货持仓与基差有时是更好的对冲拥挤代理，见对冲成本课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>情绪通过噪声交易者需求进入价格，约束下更难被套利纠正（Shleifer–Vishny；A 股再加涨跌停与 T+1）。高融资 + 高换手是杠杆投机的公开足迹，随后收益弱与去杠杆、涨跌停缺腿一致。把它当因果「情绪」还是「杠杆风险」，识别上依赖制度冲击：保证金上调后融资被迫下降，若随后收益改善，更接近杠杆渠道。</p><p>Baker–Wurgler 的美股构造不能原样移植：A 股 IPO、换手、股利的制度不同。移植的是「用公开行为代理不可观测情绪」这一方法，不是六个指标的系数。</p>',17)),(e(),s(u,null,{default:n(()=>[h(r,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20TD%0A%20%20Fin%5B%22%E8%9E%8D%E8%B5%84%E4%BD%99%E9%A2%9D%22%5D%20--%3E%20Lev%5B%22%E6%9D%A0%E6%9D%86%E5%A4%9A%E5%A4%B4%E7%83%AD%E5%BA%A6%22%5D%0A%20%20Short%5B%22%E8%9E%8D%E5%88%B8%E4%BD%99%E9%87%8F%22%5D%20--%3E%20Sup%5B%22%E4%BE%9B%E7%BB%99%E7%BA%A6%E6%9D%9F%20%2B%20%E7%A9%BA%E5%A4%B4%22%5D%0A%20%20TO%5B%22%E6%8D%A2%E6%89%8B%22%5D%20--%3E%20Spec%5B%22%E6%8A%95%E6%9C%BA%E4%BB%A3%E7%90%86%22%5D%0A%20%20Pol%5B%22%E4%B8%A4%E8%9E%8D%E4%B8%8E%E7%A8%8B%E5%BA%8F%E5%8C%96%E6%94%BF%E7%AD%96%22%5D%20--%3E%20Fin%0A%20%20Pol%20--%3E%20Short%0A%20%20Lev%20--%3E%20Sent%5B%22%E6%9D%A1%E4%BB%B6%E6%9A%B4%E9%9C%B2%22%5D%0A%20%20Spec%20--%3E%20Sent%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不提供利用未公开两融客户明细或诱导散户加杠杆的方法。公开统计是聚合。本课不构成「融资盘将崩」的交易指令。指数与行业的两融集中度另有风险含义，须单独看。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>融资与融券必须分列；融券余量首先是供给政策。</li><li>换手当 A 股投机代理，锁定日不可比；披露要点-in-time。</li><li>情绪指标须与监管日历正交，并预先登记用法。</li><li>出处：Baker and Wurgler, <em>JF</em>, 2006；Liu, Stambaugh and Yuan, <em>JFE</em>, 2019；交易所两融公开数据。</li></ul>',4))])}const D=i(E,[["render",c]]);export{S as __pageData,D as default};
